class PoseErrorBoundary extends Component<{children:ReactNode;fallback:ReactNode},{failed:boolean}>{
  state={failed:false};
  static getDerivedStateFromError(){return{failed:true}}
  componentDidCatch(error:unknown){console.error("Pose rig failed to initialize",error)}
  render(){return this.state.failed?this.props.fallback:this.props.children}
}

