        {neuralNodes.map(([x,y,delay],index)=><i className="neural-node" key={`${x}-${y}`} style={{"--node-x":x,"--node-y":y,"--node-delay":delay,"--node-size":`${index%4===0?13:index%3===0?9:6}px`} as CSSProperties}/>) }
