  async function generateImagePrompt(renderImage=false){
    const workflow:ImageWorkflow=renderImage?imageWorkflow:"text-to-image";
    const concept=workflow==="text-to-image"?imageConcept.trim():imageBriefNotes.trim()||(workflow==="image-to-image"?t("workflowImageDesc"):t("workflowMultiDesc"));
    if(!concept)return;
    if((!apiKey.trim()&&!savedKeyMatches)||!generationModel.trim()){setImagePrompt(t("configRequired"));setSettingsOpen(true);setProfileOpen(false);return}
    if(renderImage&&!accountImageConfig){setImageConfigStatus(t("imageEngineMissing"));setSettingsOpen(true);setProfileOpen(false);return}
    const references=renderImage?(workflow==="text-to-image"?[]:workflow==="image-to-image"?promptReferences.slice(0,1):promptReferences.slice(0,6)):pipelinePromptReferences.slice(0,1);
    if(workflow==="image-to-image"&&references.length!==1){setReferenceError(t("singleReferenceRequired"));return}
    if(workflow==="multi-reference"&&references.length<2){setReferenceError(t("multiReferenceRequired"));return}
    setImageGenerating(true);setImagePrompt("");setImagePromptCore("");setGeneratedImage(null);setImageRenderStatus("");
    try{
      const promptTarget=renderImage&&accountImageConfig?imagePromptFamily(accountImageConfig.model):imageModel;
      const response=await fetch("/api/generate",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({mode:"image-prompt",locale,imageWorkflow:workflow,concept,purpose:imagePurpose,style:imageStyle,aspect:imageAspect,imageModel:promptTarget,referenceNotes:renderImage?imageBriefNotes.trim():pipelineSource?.detail||"",referenceImages:references.map(item=>({data:item.src,name:item.name,role:item.role,note:item.note.trim()})),providerConfig:activeProviderConfig()})});
      const data=await response.json();
      if(!response.ok)throw new Error(data?.error||"图片提示词生成失败。");
      setImagePromptCore(data.prompt);
      setImagePrompt(`${data.prompt}${data.negativePrompt?`\n\nNEGATIVE / ${t("negative")}\n${data.negativePrompt}`:""}${data.visualAnalysis?`\n\nVISUAL REFERENCE ANALYSIS / ${t("analysis")}\n${data.visualAnalysis}`:""}`);
      if(renderImage)try{await renderGeneratedImage(data.prompt,references,workflow)}catch(error){setImageRenderStatus(error instanceof Error?error.message:t("imageGenerationFailed"))}
    }catch(error){setImagePrompt(error instanceof Error?error.message:t("generationFailed"))}
    finally{setImageGenerating(false)}
  }
  async function requestGeneratedImage(prompt:string,workflow:ImageWorkflow,aspect:string,references:PromptReference[],onStatus:(value:string)=>void){
    if(!accountImageConfig)throw new Error(t("imageEngineMissing"));
    const response=await fetch("/api/generate-image",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({prompt,workflow,aspect,references:references.map(item=>({data:item.src,role:item.role,note:item.note.trim()}))})});
    let data=await response.json();if(!response.ok)throw new Error(data?.error||t("imageGenerationFailed"));
    if(data.status==="pending"){
      onStatus(t("imageTaskQueued"));
      const query=data.taskId?`taskId=${encodeURIComponent(data.taskId)}`:`pollToken=${encodeURIComponent(data.pollToken)}`;
      for(let attempt=0;attempt<90&&data.status==="pending";attempt++){
        await new Promise(resolve=>window.setTimeout(resolve,1600));
        const progress=await fetch(`/api/generate-image?${query}`,{cache:"no-store"});data=await progress.json();if(!progress.ok)throw new Error(data?.error||t("imageGenerationFailed"));
      }
    }
    if(data.status!=="succeeded"||!data.imageUrl)throw new Error(data?.error||t("imageGenerationFailed"));
    return{src:data.imageUrl,model:data.model||accountImageConfig.model,provider:data.provider||imageGenerationProviderById(accountImageConfig.providerId).name} as GeneratedImage;
  }
